'use client';

import { useEffect } from 'react';

// Analytics service that simulates logging page views
async function logPageView() {
  try {
    // Simulate API call to analytics service
    await fetch('/api/analytics', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        page: window.location.pathname,
        timestamp: Date.now(),
        userAgent: navigator.userAgent,
      }),
    });
  } catch (error) {
    console.warn('Analytics logging failed:', error);
  }
}

// Client component that logs page views after mount
export default function WelcomeWithAnalytics() {
  useEffect(() => {
    // Use setTimeout with 0 delay to ensure this runs after the response is sent
    setTimeout(() => {
      logPageView();
    }, 0);
  }, []);

  return (
    <div>
      <h1>Welcome to Our Application</h1>
      <p>This page view is being logged to our analytics service in the background.</p>
      <p>The logging process does not block the initial page render.</p>
    </div>
  );
}

import { unstable_after } from 'next/server';
import WelcomeWithAnalytics from './components/WelcomeWithAnalytics';

// Server component that schedules analytics logging
export default function Page() {
  // Use Next.js unstable_after to schedule work after the response is sent
  unstable_after(async () => {
    try {
      // Simulate logging to an analytics service
      await fetch('https://analytics-service.example.com/track', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          event: 'page_view',
          page: '/welcome',
          timestamp: Date.now(),
        }),
      });
    } catch (error) {
      console.warn('Analytics logging failed:', error);
    }
  });

  return (
    <main>
      <WelcomeWithAnalytics />
    </main>
  );
}

