import { unstable_noStore } from 'next/cache';
import WelcomeWithAnalytics from './components/WelcomeWithAnalytics';

// Server component that schedules analytics logging
export default function Page() {
  // Use Next.js unstable_noStore to make this component dynamic
  // and allow for background processing
  unstable_noStore();

  return (
    <main>
      <WelcomeWithAnalytics />
    </main>
  );
}

import { NextRequest, NextResponse } from 'next/server';

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();

    // Simulate logging to an external analytics service
    const analyticsData = {
      ...body,
      serverTimestamp: Date.now(),
      ip: request.ip,
      userAgent: request.headers.get('user-agent'),
    };

    // In a real application, you would send this to your analytics service
    console.log('Analytics event logged:', analyticsData);

    return NextResponse.json({ 
      success: true, 
      message: 'Page view logged successfully' 
    });
  } catch (error) {
    console.error('Analytics logging failed:', error);
    return NextResponse.json({ 
      success: false, 
      error: 'Failed to log page view' 
    }, { status: 500 });
  }
}

